package com.smritisathi.app.progress;
import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import com.google.gson.*;import com.smritisathi.app.core.*;
public class ProgressActivity extends BaseActivity {TextView score; @Override public void onCreate(Bundle b){super.onCreate(b);header("My Progress & Badges");score=UI.card(this,"Loading your latest assessment...");root.addView(score);root.addView(UI.text(this,"Keep practicing. Smriti Sathi is for cognitive engagement and monitoring, not diagnosis."));load();}void load(){ApiClient.request("GET","/assessments/patient/"+Session.id(this)+"/latest",Session.token(this),null,(ok,d,e)->{if(ok&&d.has("data")&&!d.get("data").isJsonNull()){JsonObject a=d.getAsJsonObject("data");int s=a.has("overallScore")?a.get("overallScore").getAsInt():0;score.setText("Overall Score: "+s+"\n"+label(s)+"\nRecommended difficulty: "+(a.has("recommendedDifficulty")?a.get("recommendedDifficulty").getAsString():"moderate"));}else score.setText("No assessment yet. Complete a game to see your progress!");});}String label(int s){if(s>=85)return"Excellent — wonderful work! 🏆";if(s>=70)return"Great job — keep it up! ⭐";if(s>=50)return"Good effort — practice makes progress. 🌱";return"Every try counts. You're doing well. 💙";}}
